import { createHmac } from "node:crypto";
import { describe, expect, it } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const SECRET = "test-secret";
const b64 = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
function sign(payload: object, header: object = { alg: "HS256", typ: "JWT" }, secret = SECRET) {
  const data = `${b64(header)}.${b64(payload)}`;
  return `${data}.${createHmac("sha256", secret).update(data).digest("base64url")}`;
}
const future = () => Math.floor(Date.now() / 1000) + 60;

describe("verifyToken", () => {
  it("accepts a validly signed, unexpired token", () => {
    const exp = future();
    expect(verifyToken(sign({ sub: "u1", exp }), SECRET)).toEqual({ sub: "u1", exp });
  });

  it("rejects expired sessions", () => {
    expect(() => verifyToken(sign({ sub: "u1", exp: 1 }), SECRET)).toThrow("expired");
  });

  it("rejects tokens without an expiry so sessions cannot live forever", () => {
    expect(() => verifyToken(sign({ sub: "u1" }), SECRET)).toThrow();
  });

  it("rejects tokens forged with a different secret", () => {
    expect(() => verifyToken(sign({ sub: "u1", exp: future() }, undefined, "other"), SECRET)).toThrow("signature");
  });

  it("rejects tampered claims", () => {
    const [h, , s] = sign({ sub: "u1", exp: future() }).split(".");
    expect(() => verifyToken(`${h}.${b64({ sub: "admin", exp: future() })}.${s}`, SECRET)).toThrow("signature");
  });

  it("rejects alg=none tokens so attackers cannot skip signing", () => {
    const t = `${b64({ alg: "none" })}.${b64({ sub: "admin", exp: future() })}.`;
    expect(() => verifyToken(t, SECRET)).toThrow();
  });

  it("rejects malformed tokens", () => {
    expect(() => verifyToken("not-a-jwt", SECRET)).toThrow();
  });
});

